package org.apache.commons.math3.optim.nonlinear.vector.jacobian;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.function.Function;
import org.apache.commons.math3.exception.ConvergenceException;
import org.apache.commons.math3.exception.MathInternalError;
import org.apache.commons.math3.exception.MathUnsupportedOperationException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.linear.ArrayRealVector;
import org.apache.commons.math3.linear.BlockRealMatrix;
import org.apache.commons.math3.linear.DecompositionSolver;
import org.apache.commons.math3.linear.LUDecomposition;
import org.apache.commons.math3.linear.QRDecomposition;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.linear.SingularMatrixException;
import org.apache.commons.math3.optim.ConvergenceChecker;
import org.apache.commons.math3.optim.InitialGuess;
import org.apache.commons.math3.optim.PointValuePair;
import org.apache.commons.math3.optim.PointVectorValuePair;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.optim.nonlinear.vector.jacobian.AbstractJacobianOptimizer;
import org.apache.commons.math3.optim.nonlinear.vector.jacobian.ConvergenceChecker;
import org.apache.commons.math3.optim.nonlinear.vector.jacobian.PointVectorValuePair;
import org.apache.commons.math3.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Unit tests for GaussNewtonOptimizer.doOptimize().
 * Since GaussNewtonOptimizer is an abstract class or a class with protected methods 
 * (computeObjectiveValue, computeResiduals, etc.), we use a Mockito spy or a subclass 
 * to control the internal behavior for testing purposes.
 */
public class GaussNewtonOptimizer_doOptimize_TriageGen1Test {

    private ConvergenceChecker<PointVectorValuePair> mockChecker;
    private TestGaussNewtonOptimizer optimizer;

    // Concrete implementation for testing purposes to access protected methods
    private static class TestGaussNewtonOptimizer extends GaussNewtonOptimizer {
        private double[] target;
        private double[][] weight;
        private double[] startPoint;
        private boolean useLU;

        // Mockable components
        public Function<double[], double[]> objectiveFunc;
        public Function<double[], double[]> residualsFunc;
        public Function<double[], org.apache.commons.math3.linear.RealMatrix> jacobianFunc;
        public Function<double[], Double> costFunc;

        public TestGaussNewtonOptimizer(boolean useLU, ConvergenceChecker<PointVectorValuePair> checker) {
            super(useLU, checker);
            this.useLU = useLU;
        }

        @Override
        protected void checkParameters() {
            if (target == null || weight == null || startPoint == null) {
                throw new IllegalArgumentException();
            }
        }

        @Override
        protected double[] computeObjectiveValue(double[] point) {
            return objectiveFunc.apply(point);
        }

        @Override
        protected double[] computeResiduals(double[] objective) {
            return residualsFunc.apply(objective);
        }

        @Override
        protected org.apache.commons.math3.linear.RealMatrix computeWeightedJacobian(double[] point) {
            return jacobianFunc.apply(point);
        }

        @Override
        protected double computeCost(double[] residuals) {
            return costFunc.apply(residuals);
        }

        @Override
        protected double[] getTarget() { return target; }

        @Override
        protected org.apache.commons.math3.linear.RealMatrix getWeight() {
            org.apache.commons.math3.linear.RealMatrix m = new org.apache.commons.math3.linear.Array2DRowRealMatrix(weight);
            return m;
        }

        @Override
        protected double[] getStartPoint() { return startPoint; }
    }

    @Before
    public void setUp() {
        mockChecker = mock(ConvergenceChecker.class);
        optimizer = new TestGaussNewtonOptimizer(true, mockChecker);

        // Default valid setup
        optimizer.target = new double[]{1.0};
        optimizer.weight = new double[][]{{1.0}};
        optimizer.startPoint = new double[]{0.5};

        optimizer.objectiveFunc = p -> new double[]{p[0] * p[0]};
        optimizer.residualsFunc = obj -> new double[]{obj[0] - 1.0};
        optimizer.jacobianFunc = p -> new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{2 * p[0]}});
        optimizer.costFunc = res -> res[0] * res[0];
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCheckParametersFails() {
        optimizer.target = null;
        optimizer.doOptimize();
    }

    @Test(expected = NullArgumentException.class) // Assuming NullArgumentException is the class name in the source
    public void testNullCheckerThrowsException() {
        // Re-instantiate with null checker via a way that bypasses the constructor if needed, 
        // but here we simulate the checker being null after construction.
        TestGaussNewtonOptimizer nullCheckerOptimizer = new TestGaussNewtonOptimizer(true, null) {
            @Override
            protected ConvergenceChecker<PointVectorValuePair> getConvergenceChecker() {
                return null;
            }
        };
        nullCheckerOptimizer.target = new double[]{1.0};
        nullCheckerOptimizer.weight = new double[][]{{1.0}};
        nullCheckerOptimizer.startPoint = new double[]{0.5};
        nullCheckerOptimizer.objectiveFunc = p -> new double[]{0.0};
        nullCheckerOptimizer.residualsFunc = o -> new double[]{0.0};
        nullCheckerOptimizer.jacobianFunc = p -> new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{1.0}});

        nullCheckerOptimizer.doOptimize();
    }

    @Test
    public void testDoOptimizeSuccessLU() {
        when(mockChecker.converged(anyInt(), any(), any())).thenReturn(true);

        PointVectorValuePair result = optimizer.doOptimize();

        assertNotNull(result);
        verify(mockChecker, times(1)).converged(anyInt(), any(), any());
    }

    @Test
    public void testDoOptimizeSuccessQR() {
        // Test the 'else' branch for useLU
        TestGaussNewtonOptimizer qrOptimizer = new TestGaussNewtonOptimizer(false, mockChecker);
        qrOptimizer.target = new double[]{1.0};
        qrOptimizer.weight = new double[][]{{1.0}};
        qrOptimizer.startPoint = new double[]{0.5};
        qrOptimizer.objectiveFunc = p -> new double[]{p[0]};
        qrOptimizer.residualsFunc = obj -> new double[]{obj[0] - 1.0};
        qrOptimizer.jacobianFunc = p -> new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{1.0}});
        qrOptimizer.costFunc = res -> 0.0;

        when(mockChecker.converged(anyInt(), any(), any())).thenReturn(true);

        PointVectorValuePair result = qrOptimizer.doOptimize();
        assertNotNull(result);
    }

    @Test(expected = ConvergenceException.class)
    public void testSingularMatrixThrowsConvergenceException() {
        when(mockChecker.converged(anyInt(), any(), any())).thenReturn(false);
        // Force a singular matrix by providing a zero Jacobian
        optimizer.jacobianFunc = p -> new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{0.0}});

        // We need to ensure it doesn't loop forever, but a singular matrix should trigger the catch block
        optimizer.doOptimize();
    }

    @Test
    public void testIterationAndConvergence() {
        // Simulate two iterations: first fails convergence, second succeeds
        when(mockChecker.converged(eq(1), any(), any())).thenReturn(false);
        when(mockChecker.converged(eq(2), any(), any())).thenReturn(true);

        PointVectorValuePair result = optimizer.doOptimize();

        assertNotNull(result);
        verify(mockChecker, times(2)).converged(anyInt(), any(), any());
    }

    @Test(expected = MathInternalError.class)
    public void testNeverConvergedThrowsInternalError() {
        // This is hard to trigger naturally without an infinite loop, 
        // but we simulate it by forcing the checker to always return false 
        // and making the math result in a state that would eventually hit the end of the method.
        // Since the loop is 'for (boolean converged = false; !converged;)', 
        // if we could somehow bypass the return, it would throw.
        // In a real test environment, we might use a mock that throws an exception to break the loop,
        // but to reach the 'throw new MathInternalError()', we'd need to break the loop logic.
        // Given the code structure, this is almost impossible unless the loop condition is bypassed.
        // However, we can mock the checker to throw an exception to test the catch block if needed,
        // but the requirement is to cover the line.

        // To actually hit the line, we'd need to bypass the 'return' and 'throw' inside the loop.
        // This is a "dead code" scenario in most logical paths.
    }
}

// Mocking the exception class as it's not standard in Apache Commons Math but referenced in the snippet
class NullArgumentException extends RuntimeException {}
